import{_ as o,o as e,c as t,Q as r}from"./chunks/framework.a0e7c6b8.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/js/es.md","filePath":"articles/js/es.md"}'),l={name:"articles/js/es.md"},c=r('<h2 id="es8" tabindex="-1">ES8 <a class="header-anchor" href="#es8" aria-label="Permalink to &quot;ES8&quot;">​</a></h2><ol><li><p><strong>异步函数</strong>：ES8 引入了 <code>async/await</code> 语法，使得异步编程更加直观和易于理解。例如，<code>async function fetchData() { const data = await fetch(&#39;https://api.example.com/data&#39;); console.log(data); }</code>。</p></li><li><p><strong>Object.values() 和 Object.entries() 方法</strong>：ES8 引入了 <code>Object.values()</code> 和 <code>Object.entries()</code> 方法，用于获取对象的属性值和属性键值对。例如，<code>const obj = { a: 1, b: 2 }; console.log(Object.values(obj)); // [1, 2] console.log(Object.entries(obj)); // [[&#39;a&#39;, 1], [&#39;b&#39;, 2]]</code>。</p></li><li><p><strong>Object.getOwnPropertyDescriptors() 方法</strong>：ES8 引入了 <code>Object.getOwnPropertyDescriptors()</code> 方法，用于获取对象的所有属性描述符。例如，<code>const obj = { a: 1, b: 2 }; console.log(Object.getOwnPropertyDescriptors(obj));</code>。</p></li><li><p><strong>Promise.prototype.finally() 方法</strong>：ES8 引入了 <code>Promise.prototype.finally()</code> 方法，用于在 Promise 对象的状态改变后执行指定的回调函数。</p></li></ol><h2 id="es9" tabindex="-1">ES9 <a class="header-anchor" href="#es9" aria-label="Permalink to &quot;ES9&quot;">​</a></h2><ol><li><p><strong>异步迭代</strong>：ES9 引入了异步迭代的概念，使得在异步操作中使用 <code>for...of</code> 循环变得更加方便。例如，<code>async function* asyncGenerator() { for await (const x of values) { yield x; } }</code>。</p></li><li><p><strong>Rest/Spread 属性</strong>：ES9 允许在对象字面量中使用剩余（rest）和展开（spread）属性。例如，<code>const obj = { a: 1, ...rest };</code> 和 <code>const obj = { ...spread, a: 1 };</code>。</p></li><li><p><strong>模板字符串修订</strong>：ES9 对模板字符串进行了修订，允许在模板字符串中嵌套模板字符串。例如，<code>const name = &#39;World&#39;; console.log(</code>Hello, ${<code>Good morning, ${name}</code>}<code>);</code>。</p></li></ol><h2 id="es10" tabindex="-1">ES10 <a class="header-anchor" href="#es10" aria-label="Permalink to &quot;ES10&quot;">​</a></h2><ol><li><p><strong>BigInt</strong>：ES10 引入了 <code>BigInt</code> 类型，用于表示大于 <code>2^53 - 1</code> 的整数。例如，<code>const bigInt = 123n;</code>。</p></li><li><p><strong>Array.prototype.flat() 和 Array.prototype.flatMap() 方法</strong>：ES10 引入了 <code>Array.prototype.flat()</code> 和 <code>Array.prototype.flatMap()</code> 方法，用于将嵌套数组展平。例如，<code>const arr = [1, [2, [3, [4]], 5]]; console.log(arr.flat(2)); // [1, 2, 3, [4], 5]</code>。</p></li><li><p><strong>Object.fromEntries() 方法</strong>：ES10 引入了 <code>Object.fromEntries()</code> 方法，用于将键值对列表转换为对象。例如，<code>const entries = [[&#39;a&#39;, 1], [&#39;b&#39;, 2]]; console.log(Object.fromEntries(entries)); // { a: 1, b: 2 }</code>。</p></li></ol><h2 id="es11" tabindex="-1">ES11 <a class="header-anchor" href="#es11" aria-label="Permalink to &quot;ES11&quot;">​</a></h2><ol start="4"><li><p><strong>空值合并运算符（Nullish Coalescing Operator）</strong>：ES11 引入了空值合并运算符 <code>??</code>，用于在左侧操作数为 <code>null</code> 或 <code>undefined</code> 时返回右侧操作数。例如，<code>const value = null ?? &#39;default&#39;; // &#39;default&#39;</code>。</p></li><li><p><strong>可选链运算符（Optional Chaining Operator）</strong>：ES11 引入了可选链运算符 <code>?.</code>，用于在访问对象的属性或调用对象的方法之前，先检查对象是否为 <code>null</code> 或 <code>undefined</code>。例如，<code>const value = obj?.prop?.[0];</code>。</p></li><li><p><strong>BigInt</strong>：ES11 对 <code>BigInt</code> 类型进行了修订，使其可以与 <code>Number</code> 类型进行混合运算。例如，<code>const bigInt = 123n; const number = 123; console.log(bigInt + number); // 246</code>。</p></li><li><p><strong>Promise.allSettled() 方法</strong>：ES11 引入了 <code>Promise.allSettled()</code> 方法，用于等待所有 Promise 对象的状态改变，无论它们是成功还是失败。例如，<code>Promise.allSettled([Promise.resolve(1), Promise.reject(2)]) .then(results =&gt; console.log(results)); // [{ status: &#39;fulfilled&#39;, value: 1 }, { status: &#39;rejected&#39;, reason: 2 }]</code>。</p></li><li><p><strong>String.prototype.replaceAll() 方法</strong>：ES11 引入了 <code>String.prototype.replaceAll()</code> 方法，用于替换字符串中所有匹配的子字符串。例如，<code>const str = &#39;Hello, World! Hello, World!&#39;; console.log(str.replaceAll(&#39;World&#39;, &#39;JavaScript&#39;)); // &#39;Hello, JavaScript! Hello, JavaScript!&#39;</code>。</p></li><li><p><strong>全局对象全局绑定</strong>：ES11 将 <code>globalThis</code> 对象添加到全局作用域中，作为访问全局对象的统一方式。例如，<code>console.log(globalThis === window); // 在浏览器中为 true</code>。</p></li></ol><h2 id="es12" tabindex="-1">ES12 <a class="header-anchor" href="#es12" aria-label="Permalink to &quot;ES12&quot;">​</a></h2><ol><li><p><strong>数字分隔符</strong>：ES12 引入了数字分隔符，允许在数字字面量中使用下划线 <code>_</code> 作为千位分隔符。例如，<code>const number = 1_000_000;</code>。</p></li><li><p><strong>String.prototype.replaceAll() 方法</strong>：ES12 对 <code>String.prototype.replaceAll()</code> 方法进行了修订，使其可以接受一个正则表达式作为参数。例如，<code>const str = &#39;Hello, World! Hello, World!&#39;; console.log(str.replaceAll(/World/g, &#39;JavaScript&#39;)); // &#39;Hello, JavaScript! Hello, JavaScript!&#39;</code>。</p></li><li><p><strong>Promise.any() 方法</strong>：ES12 引入了 <code>Promise.any()</code> 方法，用于等待第一个成功的 Promise 对象。例如，<code>Promise.any([Promise.reject(1), Promise.reject(2)]) .then(result =&gt; console.log(result)); // Promise rejected with 1</code>。</p></li><li><p><strong>Array.prototype.sort() 的稳定性</strong>：ES12 对 <code>Array.prototype.sort()</code> 方法进行了修订，使其在排序时保持稳定性。这意味着在排序时，相等的元素会保持它们在原始数组中的顺序。</p></li></ol>',10),s=[c];function a(n,d,i,p,g,S){return e(),t("div",null,s)}const m=o(l,[["render",a]]);export{u as __pageData,m as default};
